/**
 * @file src/ui/mobile.ts
 * Mobile layout et gesture navigation
 */

import type { MobilePanelName } from './uiTypes.ts';
import { eventTargetElement } from './uiDom.ts';
import { isMobileViewport, MODAL_OPEN_SELECTOR } from './breakpoints.ts';
import { refreshTabsContainerScrollStates } from './navigation.ts';
import { initMobileScrollGate } from '../lib/mobileScrollGate.ts';
import { syncMobilePanelState } from '../stores/mobilePanel.svelte.ts';

export { isMobileViewport, MOBILE_MAX_WIDTH_PX, MOBILE_MEDIA_QUERY, MODAL_OPEN_SELECTOR } from './breakpoints.ts';

export const MOBILE_PANEL_CHANGED_EVENT = 'poketime:mobile-panel-changed' as const;

function notifyMobilePanelChanged(panelName: MobilePanelName): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(MOBILE_PANEL_CHANGED_EVENT, { detail: panelName }));
}

/** Skip 60fps combat DOM render when another mobile panel is active. */
export function shouldSkipCombatRenderOnMobile(): boolean {
    if (!isMobileViewport()) return false;
    return !document.querySelector('.combat-area.mobile-active');
}

let touchStartX = 0;
let touchEndX = 0;
let touchStartY = 0;
let touchEndY = 0;
let touchStartTarget: EventTarget | null = null;

const SWIPE_THRESHOLD = 60;
const SWIPE_VERTICAL_TOLERANCE = 0.6;
const SWIPE_PANEL_COOLDOWN_MS = 320;

let mobileTouchListenersBound = false;
let activeTouchId: number | null = null;
let lastSwipePanelSwitchAt = 0;

const MOBILE_SWIPE_HINT_KEY = 'poketime:mobileSwipeHintSeen';

const panelScrollTops: Partial<Record<MobilePanelName, number>> = {};

export function dismissMobileSwipeHint(): void {
    document.getElementById('mobileSwipeHint')?.remove();
    try {
        localStorage.setItem(MOBILE_SWIPE_HINT_KEY, '1');
    } catch {
        /* quota / private mode */
    }
}

function maybeShowMobileSwipeHint(): void {
    if (!isMobileViewport()) return;
    if (isModalOpen()) return;
    try {
        if (localStorage.getItem(MOBILE_SWIPE_HINT_KEY) === '1') return;
    } catch {
        return;
    }
    if (document.getElementById('mobileSwipeHint')) return;

    const hint = document.createElement('div');
    hint.id = 'mobileSwipeHint';
    hint.className = 'mobile-swipe-hint';
    hint.setAttribute('role', 'status');
    hint.innerHTML = '<span class="mobile-swipe-hint-text">Glissez vers la gauche pour Équipe et Extras</span>';
    hint.addEventListener('click', dismissMobileSwipeHint);
    document.body.appendChild(hint);
    window.setTimeout(dismissMobileSwipeHint, 7000);
}

const SWIPE_BLOCK_SELECTOR = [
    '.creature-card',
    '.tabs-container',
    '.sub-tabs-container',
    '.modal-overlay',
    '.stats-modal',
    '.quest-completion-modal',
    '.save-slot-boot-modal',
    '.compact-popup',
    '.js-modal-overlay',
    '#captureModal',
    '.zone-map',
    '[data-no-swipe]',
].join(',');

function getPanelElement(panelName: MobilePanelName): HTMLElement | null {
    switch (panelName) {
        case 'combat':
            return document.querySelector('.combat-area');
        case 'team':
            return document.querySelector('.team-area');
        case 'extras':
            return document.getElementById('secondaryContent');
        default:
            return null;
    }
}

function getExtrasActiveTabScrollElement(): HTMLElement | null {
    const root = document.getElementById('secondaryContent');
    const activeTab = root?.querySelector(':scope > .tab-content.active');
    if (!(activeTab instanceof HTMLElement)) return null;
    if (activeTab.id === 'boutiqueTab') {
        const shopScroll = activeTab.querySelector('.sub-tab-content:not([hidden]) .shop-subtab-scroll');
        return shopScroll instanceof HTMLElement ? shopScroll : activeTab;
    }
    return activeTab;
}

export function getActiveMobilePanel(): MobilePanelName | null {
    if (document.querySelector('.combat-area.mobile-active')) return 'combat';
    if (document.querySelector('.team-area.mobile-active')) return 'team';
    if (document.querySelector('.secondary-content.mobile-active')) return 'extras';
    return null;
}

export function syncMobilePanelStateFromDom(): MobilePanelName | null {
    if (!isMobileViewport()) {
        syncMobilePanelState(null);
        return null;
    }
    const panel = getActiveMobilePanel() ?? 'combat';
    syncMobilePanelState(panel);
    return panel;
}

function saveActivePanelScroll(): void {
    for (const name of ['combat', 'team', 'extras'] as const) {
        const el = getPanelElement(name);
        if (!el?.classList.contains('mobile-active')) continue;
        if (name === 'extras') {
            const scrollEl = getExtrasActiveTabScrollElement();
            panelScrollTops[name] = scrollEl?.scrollTop ?? 0;
        } else {
            panelScrollTops[name] = el.scrollTop;
        }
        return;
    }
}

function updateMobileNavState(panelName: MobilePanelName): void {
    document.querySelectorAll('.mobile-nav-btn').forEach((btn) => {
        if (!(btn instanceof HTMLElement)) return;
        const isActive = btn.dataset.panel === panelName;
        btn.classList.toggle('active', isActive);
        if (isActive) {
            btn.setAttribute('aria-current', 'page');
        } else {
            btn.removeAttribute('aria-current');
        }
    });
}

type PanelTransitionDirection = 'left' | 'right' | 'none';

function flashPanelTransition(el: HTMLElement, direction: PanelTransitionDirection): void {
    if (direction === 'none') return;
    el.classList.remove('mobile-panel-from-left', 'mobile-panel-from-right');
    void el.offsetWidth;
    el.classList.add(direction === 'left' ? 'mobile-panel-from-right' : 'mobile-panel-from-left');
    window.setTimeout(() => {
        el.classList.remove('mobile-panel-from-left', 'mobile-panel-from-right');
    }, 240);
}

export function switchMobilePanel(panelName: string, transition: PanelTransitionDirection = 'none'): void {
    if (panelName !== 'combat' && panelName !== 'team' && panelName !== 'extras') return;
    if (!isMobileViewport()) return;

    saveActivePanelScroll();

    const combatArea = document.querySelector('.combat-area');
    const teamArea = document.querySelector('.team-area');
    const secondaryContent = document.getElementById('secondaryContent');

    [combatArea, teamArea, secondaryContent].forEach((el) => {
        if (el) el.classList.remove('mobile-active');
    });

    const target = getPanelElement(panelName);
    if (target) {
        target.classList.add('mobile-active');
        const saved = panelScrollTops[panelName];
        if (saved !== undefined) {
            if (panelName === 'extras') {
                const scrollEl = getExtrasActiveTabScrollElement();
                if (scrollEl) scrollEl.scrollTop = saved;
            } else {
                target.scrollTop = saved;
            }
        }
        flashPanelTransition(target, transition);
    }

    updateMobileNavState(panelName);
    syncMobilePanelState(panelName);
    notifyMobilePanelChanged(panelName);

    if (panelName === 'extras') {
        requestAnimationFrame(() => refreshTabsContainerScrollStates());
    }
}

export function initMobileLayout(): void {
    initMobileScrollGate();
    if (isMobileViewport()) {
        switchMobilePanel('combat');
        syncMobilePanelStateFromDom();
        window.setTimeout(maybeShowMobileSwipeHint, 900);
    }
}

export function isModalOpen(): boolean {
    return !!document.querySelector(MODAL_OPEN_SELECTOR);
}

export function handleGesture(): void {
    if (!isMobileViewport()) return;
    if (isModalOpen()) return;

    const startEl = eventTargetElement(touchStartTarget);
    if (startEl?.closest(SWIPE_BLOCK_SELECTOR)) return;

    const diffX = touchEndX - touchStartX;
    const diffY = touchEndY - touchStartY;

    if (Math.abs(diffY) > Math.abs(diffX) * SWIPE_VERTICAL_TOLERANCE) return;
    if (Math.abs(diffX) <= SWIPE_THRESHOLD) return;

    const now = Date.now();
    if (now - lastSwipePanelSwitchAt < SWIPE_PANEL_COOLDOWN_MS) return;

    dismissMobileSwipeHint();

    const currentPanel = getActiveMobilePanel();
    const panels = ['combat', 'team', 'extras'] as const;
    const currentIndex = currentPanel ? panels.indexOf(currentPanel) : -1;

    /* Nav basse : Combat (gauche) → Équipe → Extras (droite). Swipe doigt vers la gauche = panneau suivant. */
    if (diffX < 0) {
        if (currentIndex >= 0 && currentIndex < panels.length - 1) {
            const nextPanel = panels[currentIndex + 1];
            if (nextPanel) {
                lastSwipePanelSwitchAt = now;
                switchMobilePanel(nextPanel, 'left');
            }
        }
    } else if (currentIndex > 0) {
        const prevPanel = panels[currentIndex - 1];
        if (prevPanel) {
            lastSwipePanelSwitchAt = now;
            switchMobilePanel(prevPanel, 'right');
        }
    }
}

function resetActiveTouch(): void {
    activeTouchId = null;
    touchStartTarget = null;
}

function onDocumentTouchStart(e: TouchEvent): void {
    if (!isMobileViewport()) return;
    if (e.touches.length !== 1) {
        resetActiveTouch();
        return;
    }
    const t = e.touches[0];
    if (!t) return;
    activeTouchId = t.identifier;
    touchStartX = t.screenX;
    touchStartY = t.screenY;
    touchStartTarget = e.target;
}

function onDocumentTouchEnd(e: TouchEvent): void {
    if (activeTouchId === null) return;
    if (document.querySelector('.team-card-dragging, .touch-drag-active')) {
        resetActiveTouch();
        return;
    }
    const t = Array.from(e.changedTouches).find((ct) => ct.identifier === activeTouchId)
        ?? (e.changedTouches.length === 1 ? e.changedTouches[0] : undefined);
    if (!t) {
        resetActiveTouch();
        return;
    }
    touchEndX = t.screenX;
    touchEndY = t.screenY;
    handleGesture();
    resetActiveTouch();
}

export function initMobileTouchListeners(): void {
    if (mobileTouchListenersBound) return;
    mobileTouchListenersBound = true;

    document.addEventListener('touchstart', onDocumentTouchStart, { passive: true });
    document.addEventListener('touchend', onDocumentTouchEnd, { passive: true });
    document.addEventListener('touchcancel', resetActiveTouch, { passive: true });
}
