/// <reference types="svelte" />
/**
 * Store: mobile panel — active bottom-nav panel (no facade import; safe for mobile.ts).
 */

import type { MobilePanelName } from '../ui/uiTypes.ts';

class MobilePanelStore {
  activePanel = $state<MobilePanelName | null>(null);
  /** True when Extras is the visible mobile panel, or on desktop (null panel). */
  isExtrasPanelActive = $state(false);
}

export const mobilePanel = new MobilePanelStore();

export function syncMobilePanelState(panelName: MobilePanelName | null): void {
  mobilePanel.activePanel = panelName;
  mobilePanel.isExtrasPanelActive = panelName === null || panelName === 'extras';
}
